//! Error types for the payment core.

use std::fmt;

use crate::status::PaymentStatus;

/// Convenience alias for fallible payment operations.
pub type PaymentResult<T> = Result<T, PaymentError>;

/// Errors that can occur while working with [`crate::Payment`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PaymentError {
    /// An operation was attempted that is not legal in the payment's current
    /// [`PaymentStatus`].
    InvalidTransition {
        /// The operation that was attempted, e.g. `"capture"`.
        operation: &'static str,
        /// The status the payment was in when the operation was attempted.
        current: PaymentStatus,
    },
    /// An amount of zero was supplied where a strictly positive amount is
    /// required.
    ZeroAmount,
    /// A capture amount exceeds the amount still authorized for capture.
    AmountExceedsAuthorized {
        /// The amount that was requested.
        amount: u64,
        /// The amount still available to capture.
        remaining: u64,
    },
    /// A refund amount exceeds the amount captured and not yet refunded.
    AmountExceedsCaptured {
        /// The amount that was requested.
        amount: u64,
        /// The amount still available to refund.
        available: u64,
    },
    /// A currency code could not be resolved to a known ISO-4217 code.
    UnknownCurrency(String),
    /// A payment id was empty or consisted only of whitespace.
    InvalidPaymentId,
}

impl PaymentError {
    pub(crate) fn invalid_transition(operation: &'static str, current: PaymentStatus) -> Self {
        Self::InvalidTransition { operation, current }
    }
}

impl fmt::Display for PaymentError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidTransition { operation, current } => {
                write!(
                    f,
                    "operation '{operation}' is not allowed from status '{current}'"
                )
            }
            Self::ZeroAmount => write!(f, "amount must be greater than zero"),
            Self::AmountExceedsAuthorized { amount, remaining } => {
                write!(
                    f,
                    "capture amount {amount} exceeds remaining authorized amount {remaining}"
                )
            }
            Self::AmountExceedsCaptured { amount, available } => {
                write!(
                    f,
                    "refund amount {amount} exceeds captured amount available for refund {available}"
                )
            }
            Self::UnknownCurrency(code) => write!(f, "unknown ISO-4217 currency code '{code}'"),
            Self::InvalidPaymentId => write!(f, "payment id must not be empty"),
        }
    }
}

impl std::error::Error for PaymentError {}

//! The [`Payment`] entity and its lifecycle operations.

use crate::currency::Currency;
use crate::error::{PaymentError, PaymentResult};
use crate::event::{PaymentEvent, PaymentEventType};
use crate::status::PaymentStatus;

/// An amount of money expressed in the smallest currency unit (minor units),
/// e.g. cents for `USD` or kopecks for `RUB`.
///
/// Stored as an unsigned integer to avoid floating point rounding errors.
pub type Amount = u64;

/// A payment in the payment core.
///
/// A [`Payment`] holds the original amount and currency, its current lifecycle
/// [`PaymentStatus`], how much of the amount has been captured and refunded so
/// far, and an append-only journal of [`PaymentEvent`]s.
///
/// # Lifecycle
///
/// - `Created` → `Authorized` via [`authorize`](Payment::authorize)
/// - `Authorized` → `PartiallyCaptured`/`Captured` via [`capture`](Payment::capture)
/// - `Captured`/`PartiallyCaptured` → `PartiallyRefunded`/`Refunded` via
///   [`refund`](Payment::refund)
/// - `Authorized` → `Voided` via [`void`](Payment::void)
///
/// Capture and refund support partial amounts; the resulting status reflects
/// whether the full amount was consumed.
#[derive(Debug, Clone, PartialEq)]
pub struct Payment {
    id: String,
    amount: Amount,
    currency: Currency,
    status: PaymentStatus,
    captured_amount: Amount,
    refunded_amount: Amount,
    events: Vec<PaymentEvent>,
}

impl Payment {
    /// Creates a new payment in the `Created` status.
    ///
    /// # Errors
    ///
    /// Returns [`PaymentError::InvalidPaymentId`] if `id` is empty or
    /// whitespace, and [`PaymentError::ZeroAmount`] if `amount` is zero.
    pub fn new(id: impl Into<String>, amount: Amount, currency: Currency) -> PaymentResult<Self> {
        let id = id.into();
        if id.trim().is_empty() {
            return Err(PaymentError::InvalidPaymentId);
        }
        if amount == 0 {
            return Err(PaymentError::ZeroAmount);
        }

        let event = PaymentEvent::new(
            PaymentEventType::Created,
            None,
            PaymentStatus::Created,
            format!("payment '{id}' created for {amount} {currency}"),
        );

        Ok(Self {
            id,
            amount,
            currency,
            status: PaymentStatus::Created,
            captured_amount: 0,
            refunded_amount: 0,
            events: vec![event],
        })
    }

    /// Authorizes the payment, transitioning `Created` → `Authorized`.
    ///
    /// # Errors
    ///
    /// Returns [`PaymentError::InvalidTransition`] unless the payment is in the
    /// `Created` status.
    pub fn authorize(&mut self) -> PaymentResult<&PaymentEvent> {
        if self.status != PaymentStatus::Created {
            return Err(PaymentError::invalid_transition("authorize", self.status));
        }

        self.status = PaymentStatus::Authorized;
        let description = format!("payment '{}' authorized", self.id);
        Ok(self.record(PaymentEventType::Authorized, None, description))
    }

    /// Captures `amount` from the authorized amount.
    ///
    /// A capture may cover the full authorized amount (transitioning to
    /// `Captured`) or a portion of it (transitioning to `PartiallyCaptured`).
    ///
    /// # Errors
    ///
    /// - [`PaymentError::InvalidTransition`] if the payment is not
    ///   `Authorized` or `PartiallyCaptured`.
    /// - [`PaymentError::ZeroAmount`] if `amount` is zero.
    /// - [`PaymentError::AmountExceedsAuthorized`] if `amount` exceeds the
    ///   amount still available to capture.
    pub fn capture(&mut self, amount: Amount) -> PaymentResult<&PaymentEvent> {
        let current = self.status;
        if !matches!(
            current,
            PaymentStatus::Authorized | PaymentStatus::PartiallyCaptured
        ) {
            return Err(PaymentError::invalid_transition("capture", current));
        }
        if amount == 0 {
            return Err(PaymentError::ZeroAmount);
        }

        let remaining = self.amount - self.captured_amount;
        if amount > remaining {
            return Err(PaymentError::AmountExceedsAuthorized { amount, remaining });
        }

        self.captured_amount += amount;
        self.status = if self.captured_amount == self.amount {
            PaymentStatus::Captured
        } else {
            PaymentStatus::PartiallyCaptured
        };

        let description = format!("captured {amount} {}", self.currency);
        Ok(self.record(PaymentEventType::Captured, Some(amount), description))
    }

    /// Refunds `amount` from the captured amount.
    ///
    /// A refund may cover the full captured amount (transitioning to
    /// `Refunded`) or a portion of it (transitioning to `PartiallyRefunded`).
    ///
    /// # Errors
    ///
    /// - [`PaymentError::InvalidTransition`] if the payment is not `Captured`,
    ///   `PartiallyCaptured` or `PartiallyRefunded`.
    /// - [`PaymentError::ZeroAmount`] if `amount` is zero.
    /// - [`PaymentError::AmountExceedsCaptured`] if `amount` exceeds the
    ///   captured amount still available to refund.
    pub fn refund(&mut self, amount: Amount) -> PaymentResult<&PaymentEvent> {
        let current = self.status;
        if !matches!(
            current,
            PaymentStatus::Captured
                | PaymentStatus::PartiallyCaptured
                | PaymentStatus::PartiallyRefunded
        ) {
            return Err(PaymentError::invalid_transition("refund", current));
        }
        if amount == 0 {
            return Err(PaymentError::ZeroAmount);
        }

        let available = self.captured_amount - self.refunded_amount;
        if amount > available {
            return Err(PaymentError::AmountExceedsCaptured { amount, available });
        }

        self.refunded_amount += amount;
        self.status = if self.refunded_amount == self.captured_amount {
            PaymentStatus::Refunded
        } else {
            PaymentStatus::PartiallyRefunded
        };

        let description = format!("refunded {amount} {}", self.currency);
        Ok(self.record(PaymentEventType::Refunded, Some(amount), description))
    }

    /// Voids an authorization, transitioning `Authorized` → `Voided`.
    ///
    /// # Errors
    ///
    /// Returns [`PaymentError::InvalidTransition`] unless the payment is in the
    /// `Authorized` status.
    pub fn void(&mut self) -> PaymentResult<&PaymentEvent> {
        if self.status != PaymentStatus::Authorized {
            return Err(PaymentError::invalid_transition("void", self.status));
        }

        self.status = PaymentStatus::Voided;
        let description = format!("payment '{}' voided", self.id);
        Ok(self.record(PaymentEventType::Voided, None, description))
    }

    /// Returns the payment id.
    pub fn id(&self) -> &str {
        &self.id
    }

    /// Returns the original authorized amount.
    pub fn amount(&self) -> Amount {
        self.amount
    }

    /// Returns the currency.
    pub fn currency(&self) -> Currency {
        self.currency
    }

    /// Returns the current lifecycle status.
    pub fn status(&self) -> PaymentStatus {
        self.status
    }

    /// Returns the total amount captured so far.
    pub fn captured_amount(&self) -> Amount {
        self.captured_amount
    }

    /// Returns the total amount refunded so far.
    pub fn refunded_amount(&self) -> Amount {
        self.refunded_amount
    }

    /// Returns the amount still available to capture.
    pub fn available_for_capture(&self) -> Amount {
        self.amount - self.captured_amount
    }

    /// Returns the captured amount still available to refund.
    pub fn available_for_refund(&self) -> Amount {
        self.captured_amount - self.refunded_amount
    }

    /// Returns the append-only event journal, in chronological order.
    pub fn events(&self) -> &[PaymentEvent] {
        &self.events
    }

    /// Returns the most recent journal entry, if any.
    pub fn last_event(&self) -> Option<&PaymentEvent> {
        self.events.last()
    }

    fn record(
        &mut self,
        event_type: PaymentEventType,
        amount: Option<Amount>,
        description: String,
    ) -> &PaymentEvent {
        let event = PaymentEvent::new(event_type, amount, self.status, description);
        self.events.push(event);
        self.events.last().expect("event was just pushed")
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::error::PaymentError;

    fn new_payment() -> Payment {
        Payment::new("pay_test", 1_000, Currency::USD).unwrap()
    }

    #[test]
    fn new_payment_starts_created_with_event() {
        let payment = new_payment();
        assert_eq!(payment.id(), "pay_test");
        assert_eq!(payment.status(), PaymentStatus::Created);
        assert_eq!(payment.amount(), 1_000);
        assert_eq!(payment.currency(), Currency::USD);
        assert_eq!(payment.captured_amount(), 0);
        assert_eq!(payment.refunded_amount(), 0);
        assert_eq!(payment.events().len(), 1);
        assert_eq!(payment.events()[0].event_type(), PaymentEventType::Created);
        assert_eq!(payment.events()[0].status_after(), PaymentStatus::Created);
    }

    #[test]
    fn rejects_empty_id() {
        assert_eq!(
            Payment::new("", 100, Currency::USD),
            Err(PaymentError::InvalidPaymentId)
        );
        assert_eq!(
            Payment::new("   ", 100, Currency::USD),
            Err(PaymentError::InvalidPaymentId)
        );
    }

    #[test]
    fn rejects_zero_amount() {
        assert_eq!(
            Payment::new("p", 0, Currency::USD),
            Err(PaymentError::ZeroAmount)
        );
    }

    #[test]
    fn authorize_transitions_and_records_event() {
        let mut payment = new_payment();
        payment.authorize().unwrap();
        assert_eq!(payment.status(), PaymentStatus::Authorized);
        assert_eq!(payment.events().len(), 2);
        assert_eq!(
            payment.events()[1].event_type(),
            PaymentEventType::Authorized
        );
    }

    #[test]
    fn authorize_twice_fails() {
        let mut payment = new_payment();
        payment.authorize().unwrap();
        let err = payment.authorize().unwrap_err();
        assert_eq!(
            err,
            PaymentError::InvalidTransition {
                operation: "authorize",
                current: PaymentStatus::Authorized,
            }
        );
    }

    #[test]
    fn capture_full_amount() {
        let mut payment = new_payment();
        payment.authorize().unwrap();
        payment.capture(1_000).unwrap();
        assert_eq!(payment.status(), PaymentStatus::Captured);
        assert_eq!(payment.captured_amount(), 1_000);
    }

    #[test]
    fn partial_capture_then_full() {
        let mut payment = new_payment();
        payment.authorize().unwrap();

        payment.capture(400).unwrap();
        assert_eq!(payment.status(), PaymentStatus::PartiallyCaptured);
        assert_eq!(payment.captured_amount(), 400);
        assert_eq!(payment.available_for_capture(), 600);

        payment.capture(600).unwrap();
        assert_eq!(payment.status(), PaymentStatus::Captured);
        assert_eq!(payment.available_for_capture(), 0);
    }

    #[test]
    fn capture_before_authorize_fails() {
        let mut payment = new_payment();
        let err = payment.capture(100).unwrap_err();
        assert_eq!(
            err,
            PaymentError::InvalidTransition {
                operation: "capture",
                current: PaymentStatus::Created,
            }
        );
    }

    #[test]
    fn capture_over_amount_fails() {
        let mut payment = new_payment();
        payment.authorize().unwrap();
        let err = payment.capture(1_001).unwrap_err();
        assert_eq!(
            err,
            PaymentError::AmountExceedsAuthorized {
                amount: 1_001,
                remaining: 1_000,
            }
        );
    }

    #[test]
    fn capture_zero_fails() {
        let mut payment = new_payment();
        payment.authorize().unwrap();
        assert_eq!(payment.capture(0).unwrap_err(), PaymentError::ZeroAmount);
    }

    #[test]
    fn refund_full_after_capture() {
        let mut payment = new_payment();
        payment.authorize().unwrap();
        payment.capture(1_000).unwrap();
        payment.refund(1_000).unwrap();
        assert_eq!(payment.status(), PaymentStatus::Refunded);
        assert_eq!(payment.refunded_amount(), 1_000);
        assert!(payment.status().is_terminal());
    }

    #[test]
    fn partial_refund_then_full() {
        let mut payment = new_payment();
        payment.authorize().unwrap();
        payment.capture(1_000).unwrap();

        payment.refund(300).unwrap();
        assert_eq!(payment.status(), PaymentStatus::PartiallyRefunded);
        assert_eq!(payment.refunded_amount(), 300);
        assert_eq!(payment.available_for_refund(), 700);

        payment.refund(700).unwrap();
        assert_eq!(payment.status(), PaymentStatus::Refunded);
    }

    #[test]
    fn refund_before_capture_fails() {
        let mut payment = new_payment();
        payment.authorize().unwrap();
        let err = payment.refund(100).unwrap_err();
        assert_eq!(
            err,
            PaymentError::InvalidTransition {
                operation: "refund",
                current: PaymentStatus::Authorized,
            }
        );
    }

    #[test]
    fn refund_over_captured_fails() {
        let mut payment = new_payment();
        payment.authorize().unwrap();
        payment.capture(500).unwrap();
        let err = payment.refund(600).unwrap_err();
        assert_eq!(
            err,
            PaymentError::AmountExceedsCaptured {
                amount: 600,
                available: 500,
            }
        );
    }

    #[test]
    fn void_from_authorized() {
        let mut payment = new_payment();
        payment.authorize().unwrap();
        payment.void().unwrap();
        assert_eq!(payment.status(), PaymentStatus::Voided);
        assert!(payment.status().is_terminal());
    }

    #[test]
    fn void_from_created_fails() {
        let mut payment = new_payment();
        let err = payment.void().unwrap_err();
        assert_eq!(
            err,
            PaymentError::InvalidTransition {
                operation: "void",
                current: PaymentStatus::Created,
            }
        );
    }

    #[test]
    fn terminal_refunded_rejects_further_operations() {
        let mut payment = new_payment();
        payment.authorize().unwrap();
        payment.capture(1_000).unwrap();
        payment.refund(1_000).unwrap();

        assert!(matches!(
            payment.authorize().unwrap_err(),
            PaymentError::InvalidTransition { .. }
        ));
        assert!(matches!(
            payment.capture(1).unwrap_err(),
            PaymentError::InvalidTransition { .. }
        ));
        assert!(matches!(
            payment.refund(1).unwrap_err(),
            PaymentError::InvalidTransition { .. }
        ));
    }

    #[test]
    fn full_lifecycle_journal_sequence() {
        let mut payment = new_payment();
        payment.authorize().unwrap();
        payment.capture(600).unwrap();
        payment.capture(400).unwrap();
        payment.refund(1_000).unwrap();

        let events = payment.events();
        assert_eq!(events.len(), 5);

        assert_eq!(events[0].event_type(), PaymentEventType::Created);
        assert_eq!(events[0].status_after(), PaymentStatus::Created);

        assert_eq!(events[1].event_type(), PaymentEventType::Authorized);
        assert_eq!(events[1].status_after(), PaymentStatus::Authorized);

        assert_eq!(events[2].event_type(), PaymentEventType::Captured);
        assert_eq!(events[2].amount(), Some(600));
        assert_eq!(events[2].status_after(), PaymentStatus::PartiallyCaptured);

        assert_eq!(events[3].event_type(), PaymentEventType::Captured);
        assert_eq!(events[3].amount(), Some(400));
        assert_eq!(events[3].status_after(), PaymentStatus::Captured);

        assert_eq!(events[4].event_type(), PaymentEventType::Refunded);
        assert_eq!(events[4].amount(), Some(1_000));
        assert_eq!(events[4].status_after(), PaymentStatus::Refunded);

        assert_eq!(payment.last_event(), Some(&events[4]));
    }

    #[test]
    fn failed_operation_does_not_mutate_state_or_journal() {
        let mut payment = new_payment();
        payment.authorize().unwrap();
        payment.capture(400).unwrap();

        let events_before = payment.events().len();

        assert!(payment.capture(700).is_err()); // exceeds remaining 600

        assert_eq!(payment.events().len(), events_before);
        assert_eq!(payment.status(), PaymentStatus::PartiallyCaptured);
        assert_eq!(payment.captured_amount(), 400);
    }
}

//! `payments_core` — a minimal payment core library.
//!
//! # Money
//!
//! All monetary amounts are expressed in **minor units** (`i64`): kopecks for
//! RUB, cents for USD/EUR. Floating-point arithmetic is never used for money
//! anywhere in this crate; callers format to "rubles.kopecks" only at the
//! presentation boundary.
//!
//! # Errors
//!
//! Every failure is a variant of the [`PaymentError`] enum (built with
//! `thiserror`), so callers can exhaustively `match` on the failure kind.
//!
//! # Idempotency
//!
//! [`PaymentProcessor::authorize`] takes an idempotency key. Repeating a call
//! with the same key returns the first result (success or failure) without
//! repeating the side effect, which prevents double authorization on client
//! retries.

use std::collections::HashMap;

use thiserror::Error;

/// Currency of a payment. The associated amount is always in minor units.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Currency {
    /// Russian ruble; amount in kopecks.
    Rub,
    /// US dollar; amount in cents.
    Usd,
    /// Euro; amount in cents.
    Eur,
}

/// Lifecycle status of a payment.
///
/// Transitions:
///
/// ```text
/// Pending -> Authorized   (authorize)
/// Authorized -> Captured / PartiallyCaptured   (capture)
/// Captured -> PartiallyRefunded -> Refunded    (refund)
/// Authorized -> Voided                         (void)
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PaymentStatus {
    /// Created but not yet authorized.
    Pending,
    /// Funds are held (authorized) but nothing captured.
    Authorized,
    /// Fully captured, nothing refunded.
    Captured,
    /// Partially captured; some authorized amount is still uncaptured.
    PartiallyCaptured,
    /// Fully refunded.
    Refunded,
    /// Partially refunded; some captured amount is still unrefunded.
    PartiallyRefunded,
    /// Authorization released before any capture.
    Voided,
}

/// Errors produced by the payment core.
#[derive(Debug, Clone, PartialEq, Eq, Error)]
pub enum PaymentError {
    #[error("amount must be strictly positive")]
    NonPositiveAmount,

    #[error("currency mismatch: expected {expected:?}, got {actual:?}")]
    CurrencyMismatch {
        expected: Currency,
        actual: Currency,
    },

    #[error("invalid state transition: cannot {action} from {from:?}")]
    InvalidTransition {
        from: PaymentStatus,
        action: &'static str,
    },

    #[error("capture amount {requested} exceeds authorized {authorized}")]
    CaptureExceedsAuthorized { requested: i64, authorized: i64 },

    #[error("refund amount {requested} exceeds captured {captured}")]
    RefundExceedsCaptured { requested: i64, captured: i64 },
}

/// An immutable event appended to the payment journal on every transition.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PaymentEvent {
    /// Payment created.
    Created { amount: i64, currency: Currency },
    /// Authorization succeeded (funds held).
    Authorized { idempotency_key: String },
    /// Some amount was captured.
    Captured { amount: i64 },
    /// Some amount was refunded.
    Refunded { amount: i64 },
    /// Authorization was voided.
    Voided,
}

/// A payment carrying its amount, currency, status and an event journal.
///
/// `Payment` is a value type: every state-changing method consumes `self` and
/// returns a new `Payment` (or an error), so an invalid transition can never
/// leave a half-mutated payment behind.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Payment {
    amount: i64,
    currency: Currency,
    status: PaymentStatus,
    captured: i64,
    refunded: i64,
    events: Vec<PaymentEvent>,
}

impl Payment {
    /// Creates a new `Pending` payment for `amount` minor units of `currency`.
    pub fn new(amount: i64, currency: Currency) -> Result<Self, PaymentError> {
        if amount <= 0 {
            return Err(PaymentError::NonPositiveAmount);
        }
        Ok(Self {
            amount,
            currency,
            status: PaymentStatus::Pending,
            captured: 0,
            refunded: 0,
            events: vec![PaymentEvent::Created { amount, currency }],
        })
    }

    /// Authorized (held) amount, in minor units.
    pub fn amount(&self) -> i64 {
        self.amount
    }

    pub fn currency(&self) -> Currency {
        self.currency
    }

    pub fn status(&self) -> PaymentStatus {
        self.status
    }

    /// Total captured amount, in minor units.
    pub fn captured_amount(&self) -> i64 {
        self.captured
    }

    /// Total refunded amount, in minor units.
    pub fn refunded_amount(&self) -> i64 {
        self.refunded
    }

    /// The append-only journal of events for this payment, in order.
    pub fn events(&self) -> &[PaymentEvent] {
        &self.events
    }

    /// Holds the funds: `Pending` -> `Authorized`.
    ///
    /// This is a bare transition without idempotency handling; use
    /// [`PaymentProcessor::authorize`] to deduplicate client retries by key.
    fn authorize(mut self, idempotency_key: &str) -> Result<Self, PaymentError> {
        if self.status != PaymentStatus::Pending {
            return Err(PaymentError::InvalidTransition {
                from: self.status,
                action: "authorize",
            });
        }
        self.status = PaymentStatus::Authorized;
        self.events.push(PaymentEvent::Authorized {
            idempotency_key: idempotency_key.to_owned(),
        });
        Ok(self)
    }

    /// Captures `amount` minor units of the authorized funds.
    ///
    /// Allowed from `Authorized` or `PartiallyCaptured`; the total captured
    /// amount may never exceed the authorized amount.
    pub fn capture(mut self, amount: i64) -> Result<Self, PaymentError> {
        if amount <= 0 {
            return Err(PaymentError::NonPositiveAmount);
        }
        match self.status {
            PaymentStatus::Authorized | PaymentStatus::PartiallyCaptured => {}
            other => {
                return Err(PaymentError::InvalidTransition {
                    from: other,
                    action: "capture",
                })
            }
        }
        let available = self.amount - self.captured;
        if amount > available {
            return Err(PaymentError::CaptureExceedsAuthorized {
                requested: amount,
                authorized: self.amount,
            });
        }
        self.captured += amount;
        self.status = if self.captured == self.amount {
            PaymentStatus::Captured
        } else {
            PaymentStatus::PartiallyCaptured
        };
        self.events.push(PaymentEvent::Captured { amount });
        Ok(self)
    }

    /// Refunds `amount` minor units of the captured funds.
    ///
    /// Allowed from `Captured` or `PartiallyRefunded` (i.e. only once the
    /// payment is fully captured); the total refunded amount may never exceed
    /// the captured amount.
    pub fn refund(mut self, amount: i64) -> Result<Self, PaymentError> {
        if amount <= 0 {
            return Err(PaymentError::NonPositiveAmount);
        }
        match self.status {
            PaymentStatus::Captured | PaymentStatus::PartiallyRefunded => {}
            other => {
                return Err(PaymentError::InvalidTransition {
                    from: other,
                    action: "refund",
                })
            }
        }
        let available = self.captured - self.refunded;
        if amount > available {
            return Err(PaymentError::RefundExceedsCaptured {
                requested: amount,
                captured: self.captured,
            });
        }
        self.refunded += amount;
        self.status = if self.refunded == self.captured {
            PaymentStatus::Refunded
        } else {
            PaymentStatus::PartiallyRefunded
        };
        self.events.push(PaymentEvent::Refunded { amount });
        Ok(self)
    }

    /// Releases the held funds: `Authorized` -> `Voided`.
    pub fn void(mut self) -> Result<Self, PaymentError> {
        if self.status != PaymentStatus::Authorized {
            return Err(PaymentError::InvalidTransition {
                from: self.status,
                action: "void",
            });
        }
        self.status = PaymentStatus::Voided;
        self.events.push(PaymentEvent::Voided);
        Ok(self)
    }
}

/// The outcome of a previously handled idempotency key.
#[derive(Debug, Clone)]
enum StoredAuthorization {
    Success(Payment),
    Failure(PaymentError),
}

/// Drives payments through their lifecycle, providing idempotent authorization.
#[derive(Debug, Default)]
pub struct PaymentProcessor {
    inbox: HashMap<String, StoredAuthorization>,
}

impl PaymentProcessor {
    /// Creates an empty processor with an empty idempotency inbox.
    pub fn new() -> Self {
        Self::default()
    }

    /// Authorizes `payment`, deduplicating retries by `idempotency_key`.
    ///
    /// The first call with a given key performs the authorization (recording
    /// the result). Any later call with the same key returns that first result
    /// verbatim — success returns a clone of the originally authorized payment,
    /// failure returns the original error — without touching the payment or the
    /// state machine again.
    pub fn authorize(
        &mut self,
        payment: Payment,
        idempotency_key: &str,
    ) -> Result<Payment, PaymentError> {
        if let Some(stored) = self.inbox.get(idempotency_key) {
            return match stored {
                StoredAuthorization::Success(payment) => Ok(payment.clone()),
                StoredAuthorization::Failure(error) => Err(error.clone()),
            };
        }

        let outcome = payment.authorize(idempotency_key);
        let stored = match &outcome {
            Ok(payment) => StoredAuthorization::Success(payment.clone()),
            Err(error) => StoredAuthorization::Failure(error.clone()),
        };
        self.inbox.insert(idempotency_key.to_owned(), stored);
        outcome
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn rub(amount: i64) -> Payment {
        Payment::new(amount, Currency::Rub).expect("valid amount")
    }

    fn authorized(processor: &mut PaymentProcessor, key: &str, amount: i64) -> Payment {
        processor
            .authorize(rub(amount), key)
            .expect("authorization should succeed")
    }

    #[test]
    fn new_payment_is_pending_with_created_event() {
        let payment = rub(1000);
        assert_eq!(payment.status(), PaymentStatus::Pending);
        assert_eq!(payment.amount(), 1000);
        assert_eq!(payment.currency(), Currency::Rub);
        assert_eq!(payment.captured_amount(), 0);
        assert_eq!(payment.refunded_amount(), 0);
        assert_eq!(
            payment.events(),
            &[PaymentEvent::Created {
                amount: 1000,
                currency: Currency::Rub,
            }][..]
        );
    }

    #[test]
    fn new_rejects_non_positive_amount() {
        assert_eq!(
            Payment::new(0, Currency::Rub).unwrap_err(),
            PaymentError::NonPositiveAmount
        );
        assert_eq!(
            Payment::new(-5, Currency::Usd).unwrap_err(),
            PaymentError::NonPositiveAmount
        );
    }

    #[test]
    fn authorize_transitions_pending_to_authorized() {
        let mut processor = PaymentProcessor::new();
        let payment = processor.authorize(rub(1000), "k1").unwrap();
        assert_eq!(payment.status(), PaymentStatus::Authorized);
        assert_eq!(payment.events().len(), 2);
        assert!(matches!(
            payment.events().last(),
            Some(PaymentEvent::Authorized { idempotency_key }) if idempotency_key == "k1"
        ));
    }

    #[test]
    fn authorize_is_idempotent_by_key() {
        let mut processor = PaymentProcessor::new();
        let first = processor.authorize(rub(1000), "k1").unwrap();

        // Same key, different payment: the first result is returned verbatim,
        // and no second authorization is performed.
        let second = processor
            .authorize(Payment::new(2000, Currency::Usd).unwrap(), "k1")
            .unwrap();

        assert_eq!(first, second);
        assert_eq!(second.amount(), 1000);
        assert_eq!(second.currency(), Currency::Rub);
        assert_eq!(second.events().len(), 2);
        assert_eq!(
            second
                .events()
                .iter()
                .filter(|event| matches!(event, PaymentEvent::Authorized { .. }))
                .count(),
            1
        );
    }

    #[test]
    fn authorize_different_keys_are_independent() {
        let mut processor = PaymentProcessor::new();
        let a = processor.authorize(rub(1000), "a").unwrap();
        let b = processor.authorize(rub(2000), "b").unwrap();
        assert_ne!(a, b);
        assert_eq!(a.amount(), 1000);
        assert_eq!(b.amount(), 2000);
    }

    #[test]
    fn authorize_failure_is_also_remembered() {
        let mut processor = PaymentProcessor::new();

        // Re-authorizing an already authorized payment under a fresh key fails.
        let already = authorized(&mut processor, "k1", 1000);
        let first = processor.authorize(already, "k2").unwrap_err();
        assert_eq!(
            first,
            PaymentError::InvalidTransition {
                from: PaymentStatus::Authorized,
                action: "authorize",
            }
        );

        // A retry with the same failing key returns the original failure, not a
        // fresh success.
        let retry = processor.authorize(rub(500), "k2").unwrap_err();
        assert_eq!(first, retry);
    }

    #[test]
    fn capture_full_authorized() {
        let mut processor = PaymentProcessor::new();
        let payment = authorized(&mut processor, "k", 1000).capture(1000).unwrap();
        assert_eq!(payment.status(), PaymentStatus::Captured);
        assert_eq!(payment.captured_amount(), 1000);
        assert!(matches!(
            payment.events().last(),
            Some(PaymentEvent::Captured { amount: 1000 })
        ));
    }

    #[test]
    fn capture_partial_then_remaining() {
        let mut processor = PaymentProcessor::new();
        let payment = authorized(&mut processor, "k", 1000).capture(400).unwrap();
        assert_eq!(payment.status(), PaymentStatus::PartiallyCaptured);
        assert_eq!(payment.captured_amount(), 400);

        let payment = payment.capture(600).unwrap();
        assert_eq!(payment.status(), PaymentStatus::Captured);
        assert_eq!(payment.captured_amount(), 1000);
    }

    #[test]
    fn capture_rejects_excess() {
        let mut processor = PaymentProcessor::new();
        let error = authorized(&mut processor, "k", 1000)
            .capture(1001)
            .unwrap_err();
        assert_eq!(
            error,
            PaymentError::CaptureExceedsAuthorized {
                requested: 1001,
                authorized: 1000,
            }
        );
    }

    #[test]
    fn capture_rejects_non_positive() {
        let mut processor = PaymentProcessor::new();
        let error = authorized(&mut processor, "k", 1000).capture(0).unwrap_err();
        assert_eq!(error, PaymentError::NonPositiveAmount);
    }

    #[test]
    fn capture_rejects_wrong_state() {
        let error = rub(1000).capture(1000).unwrap_err();
        assert_eq!(
            error,
            PaymentError::InvalidTransition {
                from: PaymentStatus::Pending,
                action: "capture",
            }
        );
    }

    #[test]
    fn refund_full() {
        let mut processor = PaymentProcessor::new();
        let payment = authorized(&mut processor, "k", 1000)
            .capture(1000)
            .unwrap()
            .refund(1000)
            .unwrap();
        assert_eq!(payment.status(), PaymentStatus::Refunded);
        assert_eq!(payment.refunded_amount(), 1000);
        assert!(matches!(
            payment.events().last(),
            Some(PaymentEvent::Refunded { amount: 1000 })
        ));
    }

    #[test]
    fn refund_partial_then_remaining() {
        let mut processor = PaymentProcessor::new();
        let payment = authorized(&mut processor, "k", 1000)
            .capture(1000)
            .unwrap()
            .refund(300)
            .unwrap();
        assert_eq!(payment.status(), PaymentStatus::PartiallyRefunded);
        assert_eq!(payment.refunded_amount(), 300);

        let payment = payment.refund(700).unwrap();
        assert_eq!(payment.status(), PaymentStatus::Refunded);
        assert_eq!(payment.refunded_amount(), 1000);
    }

    #[test]
    fn refund_rejects_excess() {
        let mut processor = PaymentProcessor::new();
        let error = authorized(&mut processor, "k", 1000)
            .capture(1000)
            .unwrap()
            .refund(1001)
            .unwrap_err();
        assert_eq!(
            error,
            PaymentError::RefundExceedsCaptured {
                requested: 1001,
                captured: 1000,
            }
        );
    }

    #[test]
    fn refund_rejects_before_capture() {
        let mut processor = PaymentProcessor::new();
        let error = authorized(&mut processor, "k", 1000).refund(100).unwrap_err();
        assert_eq!(
            error,
            PaymentError::InvalidTransition {
                from: PaymentStatus::Authorized,
                action: "refund",
            }
        );
    }

    #[test]
    fn void_releases_authorization() {
        let mut processor = PaymentProcessor::new();
        let payment = authorized(&mut processor, "k", 1000).void().unwrap();
        assert_eq!(payment.status(), PaymentStatus::Voided);
        assert!(matches!(payment.events().last(), Some(PaymentEvent::Voided)));
    }

    #[test]
    fn void_rejects_after_capture() {
        let mut processor = PaymentProcessor::new();
        let error = authorized(&mut processor, "k", 1000)
            .capture(1000)
            .unwrap()
            .void()
            .unwrap_err();
        assert_eq!(
            error,
            PaymentError::InvalidTransition {
                from: PaymentStatus::Captured,
                action: "void",
            }
        );
    }

    #[test]
    fn full_lifecycle_event_journal() {
        let mut processor = PaymentProcessor::new();
        let payment = authorized(&mut processor, "order-1", 1000)
            .capture(1000)
            .unwrap()
            .refund(1000)
            .unwrap();

        assert_eq!(
            payment.events(),
            &[
                PaymentEvent::Created {
                    amount: 1000,
                    currency: Currency::Rub,
                },
                PaymentEvent::Authorized {
                    idempotency_key: "order-1".to_string(),
                },
                PaymentEvent::Captured { amount: 1000 },
                PaymentEvent::Refunded { amount: 1000 },
            ][..]
        );
    }

    #[test]
    fn amounts_are_tracked_in_minor_units() {
        // 1234 minor units == 12.34 RUB — no floating point involved.
        let mut processor = PaymentProcessor::new();
        let payment = authorized(&mut processor, "k", 1234);
        assert_eq!(payment.amount(), 1234);
        let payment = payment.capture(1234).unwrap();
        assert_eq!(payment.captured_amount(), 1234);
    }
}

